import math
from fractions import Fraction

count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "percent-sum":
        s = Fraction(nums[0], nums[1]) + Fraction(nums[2], nums[3])
        print(f"  sum {s}")
        print(f"  percent {float(s * 100):.2f}%")
    elif kind == "changes":
        f = (1 + Fraction(nums[0], 100)) * (1 + Fraction(nums[1], 100))
        print(f"  factors {f}")
        print(f"  overall {float((f - 1) * 100):.2f}%")
    elif kind == "flip-power":
        v = Fraction(nums[0], nums[1]) ** nums[2]
        print(f"  value {v}")
        print(f"  decimal {float(v)}")
    elif kind == "terminates":
        f = Fraction(nums[0], nums[1])
        q = f.denominator
        while q % 2 == 0:
            q = q // 2
        while q % 5 == 0:
            q = q // 5
        print(f"  simplest {f.numerator}/{f.denominator}")
        if q == 1:
            print(f"  terminates, {float(f)}")
        else:
            print("  repeats")
    elif kind == "sci-times":
        c, e = Fraction(nums[0]) * nums[2], nums[1] + nums[3]
        print(f"  raw {c} x 10^{e}")
        while c >= 10:
            c, e = c / 10, e + 1
        print(f"  fixed {float(c)} x 10^{e}")

import math
from fractions import Fraction


def mixed(f):
    q, r = f.numerator // f.denominator, f.numerator % f.denominator
    if r == 0:
        return f"{q}"
    if q == 0:
        return f"{r}/{f.denominator}"
    return f"{q} {r}/{f.denominator}"


count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "share":
        each = Fraction(nums[0], nums[1])
        print(f"  each {each} = {mixed(each)}")
    elif kind == "servings":
        amount, size = Fraction(nums[0], nums[1]), Fraction(nums[2], nums[3])
        q = amount / size
        whole = q.numerator // q.denominator
        print(f"  {q} servings, {whole} whole, {amount - whole * size} left")
    elif kind == "sale":
        pay = nums[0] * (1 - Fraction(nums[1], 100)) * (1 + Fraction(nums[2], 100))
        print(f"  pay {pay:.2f}")
    elif kind == "map":
        print(f"  x = {Fraction(nums[1] * nums[2], nums[0])} km")
    elif kind == "split":
        part = Fraction(nums[0], nums[1] + nums[2])
        print(f"  shares {nums[1] * part:.2f} and {nums[2] * part:.2f}")
    elif kind == "garden":
        n = nums[0]
        r = math.isqrt(n)
        while n % (r * r) != 0:
            r = r - 1
        print(f"  side {r} sqrt({n // (r * r)}), about {math.sqrt(n):.2f}")

import math
from fractions import Fraction

count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "repeating":
        A, m, B, b = nums[0], nums[1], nums[2], nums[3]
        N, P = 10 ** b - 1, 10 ** m
        print(f"  x = {Fraction(A * N + B, P * N)}")
    elif kind == "square":
        a, b = nums[0], nums[1]
        print(f"  ({a} + {b})^2 = {(a + b) ** 2}, the trap gives {a * a + b * b}, off by {2 * a * b}")
    elif kind == "root":
        n = nums[0]
        r = math.isqrt(n)
        if r * r == n:
            print(f"  sqrt({n}) = {r}, rational")
        else:
            s = r
            while n % (s * s) != 0:
                s = s - 1
            form = f"{s} sqrt({n // (s * s)})"
            if s == 1:
                form = f"sqrt({n})"
            print(f"  sqrt({n}) = {form}, irrational")
    elif kind == "sigfig":
        x, n = nums[0], nums[1]
        digits, rest = 0, x
        while rest > 0:
            rest, digits = rest // 10, digits + 1
        value = x
        if digits > n:
            unit = 10 ** (digits - n)
            kept = x // unit
            if x // (unit // 10) % 10 >= 5:
                kept = kept + 1
            value = kept * unit
        print(f"  {x} to {n} figures: {value}")
